<?php
require_once dirname(__DIR__,3).'/bootstrap.php';
$code=trim((string)($_GET['code']??''));$document=null;
if($code!==''){$q=Database::connection()->prepare('SELECT d.number,d.title,d.document_date,d.status,d.revoked_at,d.revocation_reason,i.name institution_name,e.full_name signer_name FROM documents d JOIN institutions i ON i.id=d.institution_id LEFT JOIN employees e ON e.id=d.signer_employee_id WHERE d.verification_code=? LIMIT 1');$q->execute([$code]);$document=$q->fetch();}
$valid=$document&&in_array($document['status'],['signed','distributed','completed','archived'],true)&&!$document['revoked_at'];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Dokumen · SIMANTAP</title><link rel="stylesheet" href="assets/css/icons.min.css"><link rel="stylesheet" href="assets/css/app.css"><style>.verify-page{min-height:100vh;display:grid;place-items:center;padding:24px}.verify-card{width:min(100%,560px);padding:32px;text-align:center}.verify-seal{width:72px;height:72px;border-radius:50%;display:grid;place-items:center;margin:0 auto 18px;background:var(--<?= $valid?'teal':'rose' ?>-bg);color:var(--<?= $valid?'teal':'rose' ?>);font-size:36px}.verify-card h1{font-size:25px;font-weight:800}.verify-card>p{color:var(--muted)}.verify-info{text-align:left;margin:25px 0;border-top:1px solid var(--border)}.verify-info div{padding:11px 0;border-bottom:1px solid var(--border)}.verify-info small,.verify-info strong{display:block}.verify-info small{font-size:9px;color:var(--muted)}.verify-info strong{font-size:12px;margin-top:3px}</style></head><body><main class="verify-page"><section class="panel verify-card"><span class="verify-seal"><i class="ri-<?= $valid?'shield-check':'close-circle' ?>-line"></i></span><span class="status-chip <?= $valid?'teal':'rose' ?>"><?= $valid?'DOKUMEN VALID':($document&&$document['revoked_at']?'DOKUMEN DICABUT':'TIDAK DITEMUKAN') ?></span><h1><?= $valid?'Dokumen terverifikasi.':'Dokumen tidak berlaku.' ?></h1><p><?= $valid?'Dokumen diterbitkan dan tercatat resmi di SIMANTAP.':'Periksa kembali kode verifikasi atau hubungi penerbit.' ?></p><?php if($document): ?><div class="verify-info"><div><small>NOMOR SURAT</small><strong><?= htmlspecialchars($document['number']??'-') ?></strong></div><div><small>PERIHAL</small><strong><?= htmlspecialchars($document['title']) ?></strong></div><div><small>PENANDATANGAN</small><strong><?= htmlspecialchars($document['signer_name']??$document['institution_name']) ?></strong></div><div><small>TANGGAL TERBIT</small><strong><?= htmlspecialchars($document['document_date']??'-') ?></strong></div><?php if($document['revoked_at']): ?><div><small>ALASAN PENCABUTAN</small><strong><?= htmlspecialchars($document['revocation_reason']??'-') ?></strong></div><?php endif; ?></div><?php endif; ?><a class="primary-button" href="index.php?page=login">Masuk ke SIMANTAP</a></section></main></body></html>
